def abort(msg):
    print("ABORTED - no changes written.")
    print(msg)
    sys.exit(1)


def main():
    if not os.path.exists(MAIN):
        abort("Not found: " + MAIN + "\nPut this script in the legis-link-mcp folder.")
    with open(MAIN, "r", encoding="utf-8-sig", newline="") as f:
        src = f.read()
    if MARK in src:
        abort("LL-7 is already applied.")
    if "EDITIONS TO CITE (always exactly these)" not in src:
        abort("Please apply ll6_editions_and_theme.py first.")
    nl = "\r\n" if "\r\n" in src else "\n"
    out = src.replace(nl, "\n")
    for old, new, n in SWAPS:
        if out.count(old) != n:
            abort("Text not found exactly " + str(n) + " time(s):\n  " + old[:110])
        out = out.replace(old, new)
    try:
        ast.parse(out)
    except SyntaxError as e:
        abort("Patched file failed Python syntax check: " + str(e))
    stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    shutil.copy2(MAIN, MAIN + ".bak_" + stamp)
    with open(MAIN, "w", encoding="utf-8", newline="") as f:
        f.write(out.replace("\n", nl))
    print("OK - LL-7 applied (v3.9.0).")
    print("  done: verified US data - California, Texas, Florida, New York x 5 trades (20 entries)")
    print("  done: landing page shows the real number of checks")
    print("Backup saved with .bak_" + stamp)


if __name__ == "__main__":
    main()
